/* ===== v5: izin lihat/komentar/edit, komentar, bahasa di Pengaturan ===== */
function PR(r){return r=="komentator"||r=="pelihat"?r:"editor"}
var PERMS=[["editor","Editor"],["komentator","Komentator"],["pelihat","Pelihat"]];
function permOpts(v){v=PR(v);return PERMS.map(function(p){return'<option value="'+p[0]+'"'+(p[0]==v?" selected":"")+'>'+p[1]+'</option>'}).join("")}
function permNote(){return'<div class="meta" style="margin-top:6px">Pelihat: hanya melihat. Komentator: melihat dan berkomentar. Editor: melihat, berkomentar, dan mengubah.</div>'}
function cmBox(it,can){var L=it.cm||[];return'<div class="sec">Komentar</div>'+(L.length?L.map(function(c){return'<div class="idea"><div class="t"><b>'+esc(c.by)+'</b> <span class="meta">'+new Date(c.at).toLocaleString(LOC(),{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"})+'</span><div style="overflow-wrap:anywhere">'+esc(c.text)+'</div></div></div>'}).join(""):'<div class="meta">Belum ada komentar.</div>')+(can?'<div class="row" style="margin-top:8px"><input type="text" id="cm_in" placeholder="Tulis komentar" aria-label="Tulis komentar" maxlength="500"><button class="btn p" data-a="cmadd">Kirim</button></div>':"")}
